{
  "findings": [
    {
      "title": "Cross-reference to non-existent section 8.1.6 in AMG 510 dosing footnote",
      "page": 30,
      "quote": "See Section 8.1.6 for treatment beyond radiologic progression.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section 8.1.7 in docetaxel dosing footnote",
      "page": 34,
      "quote": "See Section 8.1.7 for treatment beyond radiologic progression.",
      "severity": "major"
    },
    {
      "title": "Inconsistent PK sampling schedule: Day 8 PK listed in table but not in notes",
      "page": 27,
      "quote": "Day 8 PK is to be collected ± 1 day.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent imaging schedule: table says every 6 weeks from C1D1, but footnote says imaging until progression, and LTFU imaging not specified in table",
      "page": 27,
      "quote": "Imaging every 6 weeks from cycle 1 day 1 (± 7 days) (at weeks 7, 13, 19, 25, 31, 37, 43, and 49), and then at 9-week intervals (± 7 days) thereafter",
      "severity": "minor"
    },
    {
      "title": "Inconsistent dosing instructions: 'not be taken 2 hours before' vs 'not be taken 6 hours after' unclear",
      "page": 26,
      "quote": "AMG 510 should not be taken 2 hours before the dosing time. AMG 510 dose should not be taken 6 hours after the dosing time (based on the previous day’s dose).",
      "severity": "minor"
    },
    {
      "title": "Missing information: no sample size or randomization ratio provided in excerpt",
      "page": 25,
      "quote": "Date: 06 January 2022 Page 25 of 179",
      "severity": "major"
    },
    {
      "title": "Inconsistent LTFU definition: footnote says 5 years after last subject enrolled, but table says LTFU visit 12 weeks after SFU for PD subjects",
      "page": 30,
      "quote": "LTFU will be 5 years after last subject enrolled, or until withdrawal of consent, loss to follow-up, or subject death, whichever occurs first.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent pregnancy test timing: table says within 3 days before day 1, but footnote says within 3 days before day 1 of each cycle",
      "page": 25,
      "quote": "Pregnancy test must be within 3 days before day 1 of each cycle.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent thyroid function testing: table shows X on day 1 of cycles 2-4 and 5+, but note says pre-dose on day 1 of each cycle (except cycle 1)",
      "page": 25,
      "quote": "Thyroid function testing at screening, pre-dose on day 1 of each cycle (except cycle 1), at the end of treatment, and at safety follow-up.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent cholesterol/triglyceride testing: table shows X on cycle 1 day 1, but note says every other cycle (cycle 1, 3, 5, 7, etc.)",
      "page": 26,
      "quote": "Cholesterol and triglyceride levels on pre-dose on day 1 of every other cycle (ie, cycle 1, 3, 5, 7, etc).",
      "severity": "minor"
    },
    {
      "title": "Inconsistent PRO assessment: PGIC collected on cycle 3 and 5, but table shows (X) on cycle 3 and 5 only, not on cycle 1",
      "page": 29,
      "quote": "PGIC will be collected in the clinic on day 1 of cycles 3 and cycle 5 (no collection needed at screening or cycle 1 for PGIC).",
      "severity": "minor"
    },
    {
      "title": "Inconsistent EQ-5D-5L collection: table shows X on day 5 of cycles 1-3, but note says at home for day 5 of cycles 1, 2, and 3",
      "page": 29,
      "quote": "EQ-5D-5L will also be collected during LTFU.",
      "severity": "minor"
    }
  ]
}
